/** Boid shading model: `world` shades by world-space normals, `local` by the
 * boid's own mesh-space normals so the shading is fixed to the body. */
export type LightingModel = 'world' | 'local';

export interface Params {
  /** Number of agents simulated. Changing this rebuilds the GPU state. */
  count: number;
  /** Arc-length bins used to index agents along the curve. */
  bins: number;
  /**
   * How many bins on each side of the agent's own bin are searched.
   * 0 = derive from `neighborRadius` so the window exactly covers the radius.
   */
  neighborBins: number;
  /** Maximum agents read from a single bin. */
  perBinCap: number;
  /** Maximum neighbours accumulated per agent. */
  maxNeighbors: number;

  neighborRadius: number;
  separationRadius: number;
  maxSpeed: number;
  minSpeed: number;
  maxForce: number;
  desiredSpeed: number;

  pathStrength: number;
  pathRadius: number;
  separationWeight: number;
  alignmentWeight: number;
  cohesionWeight: number;
  flowStrength: number;
  radialDamping: number;
  noiseStrength: number;
  progression: number;

  /** Rebuild the neighbour index every N frames (1 = every frame). */
  sortInterval: number;

  pathSamples: number;
  pathScale: number;

  boidScale: number;
  tubeRadius: number;
  showPath: boolean;
  autorotate: boolean;

  /** Colour of the X-axis light as a `#rrggbb` hex string. */
  boidColorX: string;
  /** Colour of the Y-axis light as a `#rrggbb` hex string. */
  boidColorY: string;
  /** Colour of the Z-axis light as a `#rrggbb` hex string. */
  boidColorZ: string;

  /** Active boid shading model. */
  lighting: LightingModel;

  /** Clamp device pixel ratio for mobile performance. */
  dprCap: number;
  /** Extra render resolution scale in [0.5, 1.5]. */
  resolutionScale: number;
  /** Simulation time multiplier. */
  timeScale: number;
}

