  neighborBins: 0,
  perBinCap: 16,
  maxNeighbors: 32,

  neighborRadius: 0.34,
  separationRadius: 0.15,
  maxSpeed: 2.2,
  minSpeed: 0.5,
  maxForce: 9,
  desiredSpeed: 1.7,

  pathStrength: 6,
  pathRadius: 0.55,
  separationWeight: 1.6,
  alignmentWeight: 0.7,
  cohesionWeight: 0.5,
  flowStrength: 2.4,
  radialDamping: 2.6,
  noiseStrength: 0.3,
  progression: 1,

  sortInterval: 1,

  pathSamples: 512,
  pathScale: 2.2,

  boidScale: 0.08,
  tubeRadius: 0.028,
  showPath: true,
  autorotate: true,
  boidColorX: '#6f9bf0',
  boidColorY: '#123a8f',
