export interface GLCaps {
  /** Whether the drawing buffer actually carries an alpha channel (as granted). */
  alpha: boolean;
  colorBufferFloat: boolean;
  uintRenderTarget: boolean;
  timerQuery: boolean;
  maxTextureSize: number;
  maxColorAttachments: number;
  maxVertexTextureUnits: number;
  renderer: string;
  vendor: string;
}

/** Probes whether an `R32UI` integer texture is usable as a color attachment. */
function probeUintRenderTarget(gl: WebGL2RenderingContext): boolean {
  const tex = gl.createTexture();
  const fbo = gl.createFramebuffer();
  if (!tex || !fbo) return false;
  let ok = false;
  try {
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.R32UI, 1, 1, 0, gl.RED_INTEGER, gl.UNSIGNED_INT, null);
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
    ok = gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
  } finally {
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.deleteFramebuffer(fbo);
    gl.deleteTexture(tex);
  }
  return ok;
}

export interface GLContextResult {
  gl: WebGL2RenderingContext;
  caps: GLCaps;
}

export class GLInitError extends Error {
  constructor(
    message: string,
    public readonly hint: string
  ) {
    super(message);
    this.name = 'GLInitError';
  }
}

export function createGLContext(
  canvas: HTMLCanvasElement,
  options: { antialias?: boolean; alpha?: boolean } = {}
): GLContextResult {
  const gl = canvas.getContext('webgl2', {
    alpha: options.alpha ?? false,
    antialias: options.antialias ?? true,
    depth: true,
    stencil: false,
    premultipliedAlpha: false,
    preserveDrawingBuffer: false,
    powerPreference: 'high-performance'
  });

  if (!gl) {
    throw new GLInitError(
      'WebGL2 is not available in this browser.',
      'This demo requires WebGL2. Try a recent Chrome, Edge, Firefox or Safari build.'
    );
  }

  const colorBufferFloat = gl.getExtension('EXT_color_buffer_float') !== null;
  const timerQuery = gl.getExtension('EXT_disjoint_timer_query_webgl2') !== null;
  const uintRenderTarget = colorBufferFloat ? probeUintRenderTarget(gl) : false;

  const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
  const renderer = debugInfo
    ? (gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL) as string)
    : (gl.getParameter(gl.RENDERER) as string);
  const vendor = debugInfo
    ? (gl.getParameter(debugInfo.UNMASKED_VENDOR_WEBGL) as string)
    : (gl.getParameter(gl.VENDOR) as string);

  const caps: GLCaps = {
    alpha: gl.getContextAttributes()?.alpha ?? false,
    colorBufferFloat,
    uintRenderTarget,
    timerQuery,
    maxTextureSize: gl.getParameter(gl.MAX_TEXTURE_SIZE) as number,
    maxColorAttachments: gl.getParameter(gl.MAX_COLOR_ATTACHMENTS) as number,
    maxVertexTextureUnits: gl.getParameter(gl.MAX_VERTEX_TEXTURE_IMAGE_UNITS) as number,
    renderer,
    vendor
  };

  if (!colorBufferFloat) {
    throw new GLInitError(
      'Float render targets (EXT_color_buffer_float) are required but missing.',
      'The GPU simulation stores agent state in floating point textures. Enable hardware acceleration or use a device that supports this WebGL2 extension.'
    );
  }

  if (!uintRenderTarget) {
    throw new GLInitError(
      'Integer render targets (R32UI) are required but missing.',
      'The spatial sort packs (bin, index) into an R32UI texture to keep bitonic passes cheap. This device does not expose an integer-renderable R32UI target.'
    );
  }

  if (caps.maxVertexTextureUnits < 3) {
    throw new GLInitError(
      'Not enough vertex texture units for instanced rendering.',
      'At least 3 vertex texture image units are required.'
    );
  }

  return { gl, caps };
}
