import type { GpuScene } from './gpuScene';
import type { OrbitCamera } from '../camera/orbit';
import type { Hud } from '../ui/hud';
import type { Params } from '../params';

/**
 * The animation loop: advances simulation time, drives the camera and the GPU
 * scene, and feeds the HUD. Deliberately owns no GL resources — it only
 * orchestrates the objects the `App` hands it.
 */
export class Loop {
  private raf = 0;
  private last = 0;
  private simTime = 0;

  constructor(
    private readonly scene: GpuScene,
    private readonly camera: OrbitCamera,
    private readonly params: Params,
    private readonly hud: Hud | null
  ) {}

  private frame = (now: number): void => {
    this.raf = requestAnimationFrame(this.frame);
    const t = now / 1000;
    let dt = this.last === 0 ? 1 / 60 : t - this.last;
    this.last = t;
    dt = Math.min(dt, 0.05);

    const cpuStart = performance.now();
    const stepDt = Math.min(dt * this.params.timeScale, 1 / 30);
    this.simTime += stepDt;

    this.camera.autorotate = this.params.autorotate;
    this.camera.update(dt);

    if (stepDt > 0) this.scene.step(stepDt, this.simTime);

    this.scene.draw(this.camera, this.simTime);

    const cpuMs = performance.now() - cpuStart;
    if (this.hud) {
      const stats = this.scene.stats();
      this.hud.tick(dt);
      this.hud.setCpu(cpuMs);
      this.hud.setGpu(stats.sortMs, stats.stepMs, stats.drawMs);
      this.hud.render({
        count: stats.count,
        arraySize: stats.arraySize,
        sortPasses: stats.sortPasses,
        renderer: stats.renderer,
        resolution: stats.resolution
      });
    }
  };

  start(): void {
    this.last = 0;
    this.raf = requestAnimationFrame(this.frame);
  }

  stop(): void {
    cancelAnimationFrame(this.raf);
  }

  dispose(): void {
    this.stop();
  }
}
