import { vec3, type Vec3 } from './math';

const HEX_RE = /^#?([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/;

/** Expands a `#rgb` / `#rrggbb` string to lowercase `#rrggbb`, or null if invalid. */
export function normalizeHex(v: string): string | null {
  const m = HEX_RE.exec(v.trim());
  if (!m) return null;
  let s = m[1];
  if (s.length === 3) s = s[0] + s[0] + s[1] + s[1] + s[2] + s[2];
  return `#${s.toLowerCase()}`;
}

/** Parses `#rgb` / `#rrggbb` into `[0,1]` components. Falls back to `fallback`. */
export function hexToRgb(hex: string, fallback: Vec3 = vec3(0, 0, 0)): Vec3 {
  const normalized = normalizeHex(hex);
  if (!normalized) return vec3(fallback[0], fallback[1], fallback[2]);
  const n = parseInt(normalized.slice(1), 16);
  return vec3(((n >> 16) & 0xff) / 255, ((n >> 8) & 0xff) / 255, (n & 0xff) / 255);
}
