/**
 * The collapsible parameter panel chrome: the slide-in toggle button and the
 * double-click-to-collapse gesture. Purely presentational — it knows nothing
 * about the parameters themselves.
 */
export class Panel {
  static mount(): Panel | null {
    const panel = document.getElementById('panel');
    const toggle = document.getElementById('panelToggle') as HTMLButtonElement | null;
    return panel && toggle ? new Panel(panel, toggle) : null;
  }

  private constructor(
    private readonly panel: HTMLElement,
    private readonly toggle: HTMLButtonElement
  ) {
    panel.classList.toggle('collapsed', window.innerWidth < 720);
    this.sync();
    toggle.addEventListener('click', this.onToggle);
    panel.addEventListener('dblclick', this.onCollapse);
  }

  private sync(): void {
    this.toggle.classList.toggle('show', this.panel.classList.contains('collapsed'));
  }

  private onToggle = (): void => {
    this.panel.classList.toggle('collapsed');
    this.panel.classList.remove('open');
    this.sync();
  };

  private onCollapse = (): void => {
    this.panel.classList.add('collapsed');
    this.sync();
  };

  dispose(): void {
    this.toggle.removeEventListener('click', this.onToggle);
    this.panel.removeEventListener('dblclick', this.onCollapse);
  }
}
