import type { InfinityPath } from './infinity';
import { createFloatTexture } from '../core/glUtils';

export interface PathTextures {
  posTex: WebGLTexture;
  tanTex: WebGLTexture;
  sampleCount: number;
}

export function createPathTextures(
  gl: WebGL2RenderingContext,
  path: InfinityPath
): PathTextures {
  const posTex = createFloatTexture(gl, path.sampleCount, 1, path.positions);
  const tanTex = createFloatTexture(gl, path.sampleCount, 1, path.tangents);
  return { posTex, tanTex, sampleCount: path.sampleCount };
}
