import type { Params } from '../params';
import { DEFAULT_PARAMS, readParam, writeParam, type ParamKey } from '../params';
import { DEFAULT_CAMERA, type CameraState } from '../camera/orbit';
import { normalizeHex } from '../core/color';

export const CONFIG_APP = 'boids-infinity-gpu';
export const CONFIG_VERSION = 1;

/**
 * Init-only parameters that are intentionally excluded from the saved config.
 * They are baked into GPU buffers / meshes at construction time and are not
 * rebuilt on load, so leaving them out keeps loading a pure state hydration.
 */
export const EXCLUDED_KEYS = ['pathSamples', 'pathScale', 'tubeRadius'] as const;
type ExcludedKey = (typeof EXCLUDED_KEYS)[number];

export type ConfigParams = Omit<Params, ExcludedKey>;

export interface BoidsConfig {
  app: string;
  version: number;
  savedAt: string;
  params: ConfigParams;
  camera: CameraState;
}

/** Every `Params` key that is serialized. */
export const CONFIG_KEYS: ParamKey[] = (Object.keys(DEFAULT_PARAMS) as ParamKey[]).filter(
  (key) => !(EXCLUDED_KEYS as readonly string[]).includes(key)
);

/** Count must land on one of the UI options so the select stays consistent. */
const COUNT_OPTIONS = [4096, 8192, 16384, 32768, 65536, 131072];

/** String params restricted to a fixed set (validated on load). */
const ENUM_OPTIONS: Partial<Record<ParamKey, readonly string[]>> = {
  lighting: ['world', 'local']
};

/** Clamp bounds for every numeric serialized key. */
const RANGES: Partial<Record<ParamKey, [number, number]>> = {
  count: [1024, 131072],
  bins: [64, 4096],
  neighborBins: [0, 128],
  perBinCap: [1, 64],
  maxNeighbors: [1, 256],
  neighborRadius: [0.02, 2],
  separationRadius: [0.005, 1],
  maxSpeed: [0.1, 10],
  minSpeed: [0, 5],
  maxForce: [0, 100],
  desiredSpeed: [0, 10],
  pathStrength: [0, 50],
  pathRadius: [0.01, 3],
  separationWeight: [0, 10],
  alignmentWeight: [0, 10],
  cohesionWeight: [0, 10],
  flowStrength: [0, 20],
  radialDamping: [0, 20],
  noiseStrength: [0, 5],
  progression: [-5, 5],
  sortInterval: [1, 30],
  boidScale: [0.005, 1],
  dprCap: [0.5, 4],
  resolutionScale: [0.25, 2],
  timeScale: [0, 5]
};

function clampValue(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

function nearestOption(v: number, options: number[]): number {
  let best = options[0];
  let bestDist = Infinity;
  for (const opt of options) {
    const d = Math.abs(opt - v);
    if (d < bestDist) {
      bestDist = d;
      best = opt;
    }
  }
  return best;
}

function asRecord(input: unknown): Record<string, unknown> {
  return input && typeof input === 'object' ? (input as Record<string, unknown>) : {};
}

export function captureConfig(params: Params, camera: CameraState): BoidsConfig {
  const p: Record<string, unknown> = {};
  for (const key of CONFIG_KEYS) p[key] = readParam(params, key);
  return {
    app: CONFIG_APP,
    version: CONFIG_VERSION,
    savedAt: new Date().toISOString(),
    params: p as ConfigParams,
    camera: { ...camera, target: [camera.target[0], camera.target[1], camera.target[2]] }
  };
}

export function serializeConfig(config: BoidsConfig): string {
  return JSON.stringify(config, null, 2);
}

function coerceCamera(input: unknown): CameraState {
  const src = asRecord(input);
  const num = (v: unknown, d: number): number =>
    typeof v === 'number' && Number.isFinite(v) ? v : d;
  let target: [number, number, number] = [
    DEFAULT_CAMERA.target[0],
    DEFAULT_CAMERA.target[1],
    DEFAULT_CAMERA.target[2]
  ];
  if (Array.isArray(src.target) && src.target.length === 3 && src.target.every((x) => typeof x === 'number' && Number.isFinite(x))) {
    target = [src.target[0] as number, src.target[1] as number, src.target[2] as number];
  }
  return {
    yaw: num(src.yaw, DEFAULT_CAMERA.yaw),
    pitch: num(src.pitch, DEFAULT_CAMERA.pitch),
    distance: num(src.distance, DEFAULT_CAMERA.distance),
    target,
    fov: num(src.fov, DEFAULT_CAMERA.fov)
  };
}

function coerceParams(input: unknown): ConfigParams {
  const src = asRecord(input);
  const out: Record<string, unknown> = {};
  for (const key of CONFIG_KEYS) {
    const def = DEFAULT_PARAMS[key];
    const value = src[key];
    if (typeof def === 'number') {
      let result = def;
      if (typeof value === 'number' && Number.isFinite(value)) {
        const [lo, hi] = RANGES[key] ?? [-1e9, 1e9];
        result = clampValue(value, lo, hi);
        if (key === 'count') result = nearestOption(result, COUNT_OPTIONS);
        else if (key === 'sortInterval') result = Math.round(result);
      }
      out[key] = result;
    } else if (typeof def === 'string') {
      const options = ENUM_OPTIONS[key];
      if (options) {
        out[key] = typeof value === 'string' && options.includes(value) ? value : def;
      } else {
        const hex = typeof value === 'string' ? normalizeHex(value) : null;
        out[key] = hex ?? def;
      }
    } else {
      out[key] = typeof value === 'boolean' ? value : def;
    }
  }
  return out as ConfigParams;
}

export function parseConfig(text: string): BoidsConfig {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new Error('File is not valid JSON');
  }
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('Config root must be an object');
  }
  const obj = raw as Record<string, unknown>;
  if (obj.version !== undefined) {
    if (typeof obj.version !== 'number' || !Number.isFinite(obj.version)) {
      throw new Error('Invalid config version');
    }
    if (obj.version > CONFIG_VERSION) {
      throw new Error(`Config version ${obj.version} is newer than supported (${CONFIG_VERSION})`);
    }
  }
  const version = typeof obj.version === 'number' ? obj.version : CONFIG_VERSION;
  return {
    app: typeof obj.app === 'string' ? obj.app : CONFIG_APP,
    version,
    savedAt: typeof obj.savedAt === 'string' ? obj.savedAt : new Date().toISOString(),
    params: coerceParams(obj.params),
    camera: coerceCamera(obj.camera)
  };
}

/** Copies serialized keys onto `target`, returning the keys that actually changed. */
export function applyParams(target: Params, incoming: Partial<ConfigParams>): ParamKey[] {
  const src = incoming as Record<string, unknown>;
  const changed: ParamKey[] = [];
  for (const key of CONFIG_KEYS) {
    const value = src[key];
    if (value === undefined) continue;
    if (readParam(target, key) !== value) {
      writeParam(target, key, value);
      changed.push(key);
    }
  }
  return changed;
}
