/**
 * Thin wrapper around `EXT_disjoint_timer_query_webgl2`. Each instance owns one
 * query slot. A query result is intentionally read one or more frames later, so
 * `begin` refuses to start a new sample while the previous one is still in
 * flight (that would leak the query) and `poll` publishes it once ready. When
 * the extension is unavailable (notably iOS Safari) everything is a no-op.
 */
export class GpuTimer {
  private readonly gl: WebGL2RenderingContext;
  private readonly ext: any;
  private pending: WebGLQuery | null = null;
  private active = false;
  private available = false;
  private lastMs = 0;

  constructor(gl: WebGL2RenderingContext, enabled?: boolean) {
    this.gl = gl;
    const auto = enabled ?? true;
    this.ext = auto ? gl.getExtension('EXT_disjoint_timer_query_webgl2') : null;
    this.available = this.ext !== null;
  }

  get supported(): boolean {
    return this.available;
  }

  begin(): void {
    if (!this.available || this.pending) return;
    const q = this.gl.createQuery();
    if (!q) return;
    this.gl.beginQuery(this.ext.TIME_ELAPSED_EXT, q);
    this.pending = q;
    this.active = true;
  }

  end(): void {
    if (!this.available || !this.active) return;
    this.gl.endQuery(this.ext.TIME_ELAPSED_EXT);
    this.active = false;
  }

  poll(): number {
    if (!this.available || !this.pending) return this.lastMs;
    const gl = this.gl;
    const disjoint = gl.getParameter(this.ext.GPU_DISJOINT_EXT);
    const ready = gl.getQueryParameter(this.pending, gl.QUERY_RESULT_AVAILABLE);
    if (ready && !disjoint) {
      const ns = gl.getQueryParameter(this.pending, gl.QUERY_RESULT) as number;
      this.lastMs = ns / 1e6;
      gl.deleteQuery(this.pending);
      this.pending = null;
    } else if (disjoint) {
      gl.deleteQuery(this.pending);
      this.pending = null;
    }
    return this.lastMs;
  }

  dispose(): void {
    if (this.pending) {
      this.gl.deleteQuery(this.pending);
      this.pending = null;
    }
    this.active = false;
  }
}
