import { escapeHtml, shorten } from '../core/dom';

export class Hud {
  private frames = 0;
  private accum = 0;
  private fps = 0;
  private frameMs = 0;
  private cpuMs = 0;
  private gpuSortMs = 0;
  private gpuStepMs = 0;
  private gpuDrawMs = 0;

  constructor(private readonly el: HTMLElement) {}

  setCpu(ms: number): void {
    this.cpuMs = ms;
  }

  setGpu(sortMs: number, stepMs: number, drawMs: number): void {
    this.gpuSortMs = sortMs;
    this.gpuStepMs = stepMs;
    this.gpuDrawMs = drawMs;
  }

  tick(dt: number): void {
    this.frames++;
    this.accum += dt;
    this.frameMs = dt * 1000;
    if (this.accum >= 0.5) {
      this.fps = this.frames / this.accum;
      this.frames = 0;
      this.accum = 0;
    }
  }

  render(info: {
    count: number;
    arraySize: number;
    sortPasses: number;
    renderer: string;
    resolution: string;
  }): void {
    const fmt = (v: number) => (v > 0 ? v.toFixed(2) : 'n/a');
    this.el.innerHTML =
      `<b>${this.fps.toFixed(0)}</b> fps  <b>${this.frameMs.toFixed(1)}</b> ms\n` +
      `cpu <b>${this.cpuMs.toFixed(2)}</b> ms\n` +
      `gpu sort <b>${fmt(this.gpuSortMs)}</b>  step <b>${fmt(this.gpuStepMs)}</b>  draw <b>${fmt(this.gpuDrawMs)}</b>\n` +
      `boids <b>${info.count.toLocaleString()}</b> / ${info.arraySize.toLocaleString()} slots\n` +
      `sort <b>${info.sortPasses}</b> passes\n` +
      `res ${info.resolution}\n` +
      `${escapeHtml(shorten(info.renderer, 34))}`;
  }
}
