import { createProgram, type FullscreenQuad, type Program } from '../core/glUtils';
import {
  BOID_FRAG,
  BOID_VERT,
  EXPAND_FRAG,
  EXPAND_VERT,
  PATH_FRAG,
  PATH_VERT,
  PATTERN_FRAG,
  SKY_FRAG
} from '../shaders/render';
import { FULLSCREEN_VERT } from '../shaders/common';
import { buildBoidMesh, buildPathTube, type MeshData } from './mesh';
import { mat4Invert, mat4Multiply, mat4Perspective, mat4LookAt, vec3 } from '../core/math';
import { hexToRgb } from '../core/color';
import type { InfinityPath } from '../path/infinity';
import type { Simulation } from '../gpgpu/simulation';
import type { OrbitCamera } from '../camera/orbit';
import type { Params } from '../params';

interface GLMesh {
  vao: WebGLVertexArrayObject;
  vbo: WebGLBuffer;
  vertexCount: number;
}

/** Per-instance transform emitted by the expand pass (see EXPAND_VERT). */
const INSTANCE_FLOATS = 13; // right(3) up(3) fwd(3) pos(3) speed(1)
const INSTANCE_STRIDE = INSTANCE_FLOATS * 4;

function createMesh(gl: WebGL2RenderingContext, data: MeshData): GLMesh {
  const vao = gl.createVertexArray();
  const vbo = gl.createBuffer();
  if (!vao || !vbo) throw new Error('Failed to allocate mesh');
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
  gl.bufferData(gl.ARRAY_BUFFER, data.vertices, gl.STATIC_DRAW);
  const stride = 6 * 4;
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 3, gl.FLOAT, false, stride, 0);
  gl.enableVertexAttribArray(1);
  gl.vertexAttribPointer(1, 3, gl.FLOAT, false, stride, 3 * 4);
  gl.bindVertexArray(null);
  gl.bindBuffer(gl.ARRAY_BUFFER, null);
  return { vao, vbo, vertexCount: data.vertexCount };
}

/** How the full-screen background behind the boids is produced. */
export type Background = 'sky' | 'transparent' | 'pattern';

export class Renderer {
  private readonly gl: WebGL2RenderingContext;
  private readonly quad: FullscreenQuad;
  private readonly expandProgram: Program;
  private readonly boidProgram: Program;
  private readonly pathProgram: Program;
  private readonly skyProgram: Program;
  private readonly patternProgram: Program;
  private readonly boidMesh: GLMesh;
  private readonly pathMesh: GLMesh;
  private readonly background: Background;

  /** Instance VAO: boid mesh (attribs 0-1) + transform-feedback buffer (2-6). */
  private readonly instanceVao: WebGLVertexArrayObject;
  private readonly instanceBuffer: WebGLBuffer;
  private readonly feedback: WebGLTransformFeedback;
  private instanceCapacity = 0;

  private readonly fallbackColor = vec3(0.12, 0.36, 0.85);
  private readonly pathColor = vec3(0.35, 0.82, 1.0);
  private readonly up = vec3(0, 1, 0);

  constructor(
    gl: WebGL2RenderingContext,
    quad: FullscreenQuad,
    path: InfinityPath,
    params: Params,
    options: { background?: Background } = {}
  ) {
    this.gl = gl;
    this.quad = quad;
    this.background = options.background ?? 'sky';
    this.expandProgram = createProgram(gl, EXPAND_VERT, EXPAND_FRAG, [
      'oRight',
      'oUp',
      'oFwd',
      'oPos',
      'oSpeed'
    ]);
    this.boidProgram = createProgram(gl, BOID_VERT, BOID_FRAG);
    this.pathProgram = createProgram(gl, PATH_VERT, PATH_FRAG);
    this.skyProgram = createProgram(gl, FULLSCREEN_VERT, SKY_FRAG);
    this.patternProgram = createProgram(gl, FULLSCREEN_VERT, PATTERN_FRAG);
    this.boidMesh = createMesh(gl, buildBoidMesh());
    this.pathMesh = createMesh(gl, buildPathTube(path, params.tubeRadius, 6));

    const instanceBuffer = gl.createBuffer();
    const feedback = gl.createTransformFeedback();
    const instanceVao = gl.createVertexArray();
    if (!instanceBuffer || !feedback || !instanceVao) throw new Error('Failed to allocate instancing resources');
    this.instanceBuffer = instanceBuffer;
    this.feedback = feedback;
    this.instanceVao = instanceVao;

    gl.bindVertexArray(instanceVao);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.boidMesh.vbo);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 24, 0);
    gl.enableVertexAttribArray(1);
    gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 24, 12);
    gl.bindBuffer(gl.ARRAY_BUFFER, instanceBuffer);
    const instAttribs: [number, number, number][] = [
      [2, 3, 0],
      [3, 3, 12],
      [4, 3, 24],
      [5, 3, 36],
      [6, 1, 48]
    ];
    for (const [loc, size, offset] of instAttribs) {
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc, size, gl.FLOAT, false, INSTANCE_STRIDE, offset);
      gl.vertexAttribDivisor(loc, 1);
    }
    gl.bindVertexArray(null);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
  }

  private ensureInstanceCapacity(count: number): void {
    if (count <= this.instanceCapacity) return;
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instanceBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, count * INSTANCE_STRIDE, gl.DYNAMIC_DRAW);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    this.instanceCapacity = count;
  }

  /**
   * One vertex-shader pass over `count` points that reads each agent's state once
   * (instead of once per mesh vertex) and captures the per-instance basis into a
   * buffer via transform feedback. The main draw then uses plain instanced
   * attributes, so the render path does no vertex texture fetch at all.
   */
  private expandInstances(sim: Simulation, params: Params): void {
    const gl = this.gl;
    const count = params.count;
    this.ensureInstanceCapacity(count);

    gl.useProgram(this.expandProgram.program);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, sim.positionTexture);
    gl.uniform1i(this.expandProgram.uniforms.uPos, 0);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, sim.velocityTexture);
    gl.uniform1i(this.expandProgram.uniforms.uVel, 1);
    gl.uniform1i(this.expandProgram.uniforms.uArrayW, sim.arrayWidth);
    gl.uniform1f(this.expandProgram.uniforms.uScale, params.boidScale);

    gl.bindVertexArray(null);
    gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, this.feedback);
    gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, this.instanceBuffer);
    gl.enable(gl.RASTERIZER_DISCARD);
    gl.beginTransformFeedback(gl.POINTS);
    gl.drawArrays(gl.POINTS, 0, count);
    gl.endTransformFeedback();
    gl.disable(gl.RASTERIZER_DISCARD);
    gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, null);
    gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);
  }

  draw(
    camera: OrbitCamera,
    sim: Simulation,
    params: Params,
    time: number,
    width: number,
    height: number,
    patternScale = 1
  ): void {
    const gl = this.gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, width, height);

    const aspect = width / Math.max(height, 1);
    const proj = mat4Perspective((camera.fov * Math.PI) / 180, aspect, 0.05, 200);
    const view = mat4LookAt(camera.eye(), camera.target, this.up);
    const viewProj = mat4Multiply(proj, view);
    const invViewProj = mat4Invert(viewProj);
    const eye = camera.eye();

    gl.clearColor(0.015, 0.02, 0.04, this.background === 'transparent' ? 0 : 1);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

    if (this.background === 'sky' || this.background === 'pattern') {
      gl.disable(gl.DEPTH_TEST);
      gl.depthMask(false);
      gl.disable(gl.BLEND);
      if (this.background === 'sky') {
        gl.useProgram(this.skyProgram.program);
        gl.uniformMatrix4fv(this.skyProgram.uniforms.uInvViewProj, false, invViewProj);
        gl.uniform3fv(this.skyProgram.uniforms.uCameraPos, eye);
      } else {
        gl.useProgram(this.patternProgram.program);
        gl.uniform1f(this.patternProgram.uniforms.uScale, Math.max(patternScale, 1e-3));
      }
      this.quad.draw();
    }

    // Boids: expand agent state once, then draw instanced attributes.
    this.expandInstances(sim, params);

    gl.enable(gl.DEPTH_TEST);
    gl.depthFunc(gl.LEQUAL);
    gl.depthMask(true);
    gl.disable(gl.BLEND);
    gl.disable(gl.CULL_FACE);
    gl.useProgram(this.boidProgram.program);
    gl.uniformMatrix4fv(this.boidProgram.uniforms.uViewProj, false, viewProj);
    gl.uniform3fv(this.boidProgram.uniforms.uColorX, hexToRgb(params.boidColorX, this.fallbackColor));
    gl.uniform3fv(this.boidProgram.uniforms.uColorY, hexToRgb(params.boidColorY, this.fallbackColor));
    gl.uniform3fv(this.boidProgram.uniforms.uColorZ, hexToRgb(params.boidColorZ, this.fallbackColor));
    gl.uniform1f(this.boidProgram.uniforms.uLocal, params.lighting === 'local' ? 1 : 0);

    gl.bindVertexArray(this.instanceVao);
    gl.drawArraysInstanced(gl.TRIANGLES, 0, this.boidMesh.vertexCount, params.count);
    gl.bindVertexArray(null);

    // Glowing path ribbon (additive, drawn last so it reads as a light core)
    if (params.showPath) {
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.SRC_ALPHA, gl.ONE);
      gl.depthMask(false);
      gl.useProgram(this.pathProgram.program);
      gl.uniformMatrix4fv(this.pathProgram.uniforms.uViewProj, false, viewProj);
      gl.uniform3fv(this.pathProgram.uniforms.uCameraPos, eye);
      gl.uniform3fv(this.pathProgram.uniforms.uColor, this.pathColor);
      gl.uniform1f(this.pathProgram.uniforms.uTime, time);
      gl.bindVertexArray(this.pathMesh.vao);
      gl.drawArrays(gl.TRIANGLES, 0, this.pathMesh.vertexCount);
      gl.bindVertexArray(null);
      gl.depthMask(true);
      gl.disable(gl.BLEND);
    }
  }

  dispose(): void {
    const gl = this.gl;
    gl.deleteProgram(this.expandProgram.program);
    gl.deleteProgram(this.boidProgram.program);
    gl.deleteProgram(this.pathProgram.program);
    gl.deleteProgram(this.skyProgram.program);
    gl.deleteProgram(this.patternProgram.program);
    gl.deleteVertexArray(this.boidMesh.vao);
    gl.deleteBuffer(this.boidMesh.vbo);
    gl.deleteVertexArray(this.pathMesh.vao);
    gl.deleteBuffer(this.pathMesh.vbo);
    gl.deleteVertexArray(this.instanceVao);
    gl.deleteBuffer(this.instanceBuffer);
    gl.deleteTransformFeedback(this.feedback);
  }
}
