import { clamp, vec3, type Vec3 } from '../core/math';

export interface PointerState {
  x: number;
  y: number;
}

/** Serializable camera pose. */
export interface CameraState {
  yaw: number;
  pitch: number;
  distance: number;
  target: [number, number, number];
  fov: number;
}

export const DEFAULT_CAMERA: CameraState = {
  yaw: Math.PI * 0.25,
  pitch: 0.32,
  distance: 9,
  target: [0, 0, 0],
  fov: 48
};

export class OrbitCamera {
  fov = 48;
  target: Vec3 = vec3(0, 0, 0);
  distance = 9;
  yaw = Math.PI * 0.25;
  pitch = 0.32;
  minDistance = 2.5;
  maxDistance = 40;
  minPitch = -1.4;
  maxPitch = 1.4;
  autorotate = true;
  autoSpeed = 0.12;
  private readonly pointers = new Map<number, PointerState>();
  private lastPinch = 0;
  private dragging = false;

  constructor(private readonly canvas: HTMLCanvasElement, interactive = true) {
    if (interactive) this.attach();
  }

  private attach(): void {
    const c = this.canvas;
    c.addEventListener('pointerdown', this.onDown);
    c.addEventListener('pointermove', this.onMove);
    c.addEventListener('pointerup', this.onUp);
    c.addEventListener('pointercancel', this.onUp);
    c.addEventListener('wheel', this.onWheel, { passive: false });
    c.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  private onDown = (e: PointerEvent): void => {
    this.canvas.setPointerCapture(e.pointerId);
    this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    this.dragging = true;
    if (this.pointers.size === 2) this.lastPinch = this.pinchDistance();
  };

  private onMove = (e: PointerEvent): void => {
    const prev = this.pointers.get(e.pointerId);
    if (!prev) return;
    const dx = e.clientX - prev.x;
    const dy = e.clientY - prev.y;
    prev.x = e.clientX;
    prev.y = e.clientY;

    if (this.pointers.size === 1) {
      this.yaw -= dx * 0.006;
      this.pitch = clamp(this.pitch + dy * 0.006, this.minPitch, this.maxPitch);
    } else if (this.pointers.size === 2) {
      const d = this.pinchDistance();
      if (this.lastPinch > 0) {
        const ratio = this.lastPinch / Math.max(d, 1);
        this.distance = clamp(this.distance * ratio, this.minDistance, this.maxDistance);
      }
      this.lastPinch = d;
    }
  };

  private onUp = (e: PointerEvent): void => {
    this.pointers.delete(e.pointerId);
    if (this.pointers.size < 2) this.lastPinch = 0;
    if (this.pointers.size === 0) this.dragging = false;
  };

  private onWheel = (e: WheelEvent): void => {
    e.preventDefault();
    const factor = Math.exp(e.deltaY * 0.0012);
    this.distance = clamp(this.distance * factor, this.minDistance, this.maxDistance);
  };

  private pinchDistance(): number {
    const pts = [...this.pointers.values()];
    if (pts.length < 2) return 0;
    return Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
  }

  update(dt: number): void {
    if (this.autorotate && !this.dragging) {
      this.yaw += dt * this.autoSpeed;
    }
  }

  eye(): Vec3 {
    const cp = Math.cos(this.pitch);
    const sp = Math.sin(this.pitch);
    return vec3(
      this.target[0] + this.distance * cp * Math.sin(this.yaw),
      this.target[1] + this.distance * sp,
      this.target[2] + this.distance * cp * Math.cos(this.yaw)
    );
  }

  getState(): CameraState {
    return {
      yaw: this.yaw,
      pitch: this.pitch,
      distance: this.distance,
      target: [this.target[0], this.target[1], this.target[2]],
      fov: this.fov
    };
  }

  setState(state: Partial<CameraState>): void {
    if (typeof state.yaw === 'number' && Number.isFinite(state.yaw)) this.yaw = state.yaw;
    if (typeof state.pitch === 'number' && Number.isFinite(state.pitch)) {
      this.pitch = clamp(state.pitch, this.minPitch, this.maxPitch);
    }
    if (typeof state.distance === 'number' && Number.isFinite(state.distance)) {
      this.distance = clamp(state.distance, this.minDistance, this.maxDistance);
    }
    if (typeof state.fov === 'number' && Number.isFinite(state.fov)) {
      this.fov = clamp(state.fov, 20, 100);
    }
    if (Array.isArray(state.target) && state.target.length === 3 && state.target.every(Number.isFinite)) {
      this.target = vec3(state.target[0], state.target[1], state.target[2]);
    }
  }

  reset(): void {
    this.setState(DEFAULT_CAMERA);
  }

  dispose(): void {
    const c = this.canvas;
    c.removeEventListener('pointerdown', this.onDown);
    c.removeEventListener('pointermove', this.onMove);
    c.removeEventListener('pointerup', this.onUp);
    c.removeEventListener('pointercancel', this.onUp);
    c.removeEventListener('wheel', this.onWheel);
  }
}
