export interface InfinityPath {
  sampleCount: number;
  length: number;
  /** RGBA32F source data: xyz = point on curve (uniform arc-length), w = unused. */
  positions: Float32Array;
  /** RGBA32F source data: xyz = unit tangent, w = signed curvature magnitude. */
  tangents: Float32Array;
}

export interface PathSample {
  position: [number, number, number];
  tangent: [number, number, number];
}

/**
 * Genuinely three-dimensional figure-eight. The x axis sweeps the two lobes,
 * y gives the figure-eight pinch, and z twists the curve out of plane so the
 * ribbon is volumetric rather than flat.
 */
export function infinityPoint(t: number, a: number): [number, number, number] {
  const x = a * Math.cos(t);
  const y = a * 0.78 * Math.sin(t) * Math.cos(t);
  const z = a * 0.52 * Math.sin(t);
  return [x, y, z];
}

export function buildInfinityPath(sampleCount: number, a = 2.2): InfinityPath {
  const dense = sampleCount * 10;
  const raw = new Float32Array(dense * 3);
  for (let i = 0; i < dense; i++) {
    const t = (i / dense) * Math.PI * 2;
    const [x, y, z] = infinityPoint(t, a);
    raw[i * 3 + 0] = x;
    raw[i * 3 + 1] = y;
    raw[i * 3 + 2] = z;
  }

  const cum = new Float32Array(dense + 1);
  for (let i = 1; i <= dense; i++) {
    const p = (i - 1) * 3;
    const q = (i % dense) * 3;
    const dx = raw[q + 0] - raw[p + 0];
    const dy = raw[q + 1] - raw[p + 1];
    const dz = raw[q + 2] - raw[p + 2];
    cum[i] = cum[i - 1] + Math.hypot(dx, dy, dz);
  }
  const totalLength = cum[dense];

  const positions = new Float32Array(sampleCount * 4);
  const resampled = new Float32Array(sampleCount * 3);
  let seg = 0;
  for (let i = 0; i < sampleCount; i++) {
    const target = (i / sampleCount) * totalLength;
    while (seg < dense - 1 && cum[seg + 1] < target) seg++;
    const segLen = cum[seg + 1] - cum[seg] || 1e-6;
    const f = (target - cum[seg]) / segLen;
    const p = (seg % dense) * 3;
    const q = ((seg + 1) % dense) * 3;
    const x = raw[p + 0] + (raw[q + 0] - raw[p + 0]) * f;
    const y = raw[p + 1] + (raw[q + 1] - raw[p + 1]) * f;
    const z = raw[p + 2] + (raw[q + 2] - raw[p + 2]) * f;
    positions[i * 4 + 0] = x;
    positions[i * 4 + 1] = y;
    positions[i * 4 + 2] = z;
    positions[i * 4 + 3] = 0;
    resampled[i * 3 + 0] = x;
    resampled[i * 3 + 1] = y;
    resampled[i * 3 + 2] = z;
  }

  const tangents = new Float32Array(sampleCount * 4);
  const ds = totalLength / sampleCount;
  for (let i = 0; i < sampleCount; i++) {
    const prev = (i - 1 + sampleCount) % sampleCount;
    const next = (i + 1) % sampleCount;
    let tx = resampled[next * 3 + 0] - resampled[prev * 3 + 0];
    let ty = resampled[next * 3 + 1] - resampled[prev * 3 + 1];
    let tz = resampled[next * 3 + 2] - resampled[prev * 3 + 2];
    const len = Math.hypot(tx, ty, tz) || 1e-6;
    tx /= len;
    ty /= len;
    tz /= len;

    const ax = resampled[next * 3 + 0] - 2 * resampled[i * 3 + 0] + resampled[prev * 3 + 0];
    const ay = resampled[next * 3 + 1] - 2 * resampled[i * 3 + 1] + resampled[prev * 3 + 1];
    const az = resampled[next * 3 + 2] - 2 * resampled[i * 3 + 2] + resampled[prev * 3 + 2];
    const curvature = Math.hypot(ax, ay, az) / (ds * ds);

    tangents[i * 4 + 0] = tx;
    tangents[i * 4 + 1] = ty;
    tangents[i * 4 + 2] = tz;
    tangents[i * 4 + 3] = curvature;
  }

  return { sampleCount, length: totalLength, positions, tangents };
}

/** CPU-side sampler used for initial conditions and mesh generation. */
export function samplePath(path: InfinityPath, s: number): PathSample {
  const n = path.sampleCount;
  const scaled = ((s % 1) + 1) % 1 * n;
  const i0 = Math.floor(scaled) % n;
  const i1 = (i0 + 1) % n;
  const f = scaled - Math.floor(scaled);
  const p = path.positions;
  const t = path.tangents;
  const position: [number, number, number] = [
    p[i0 * 4 + 0] + (p[i1 * 4 + 0] - p[i0 * 4 + 0]) * f,
    p[i0 * 4 + 1] + (p[i1 * 4 + 1] - p[i0 * 4 + 1]) * f,
    p[i0 * 4 + 2] + (p[i1 * 4 + 2] - p[i0 * 4 + 2]) * f
  ];
  const tangent: [number, number, number] = [
    t[i0 * 4 + 0] + (t[i1 * 4 + 0] - t[i0 * 4 + 0]) * f,
    t[i0 * 4 + 1] + (t[i1 * 4 + 1] - t[i0 * 4 + 1]) * f,
    t[i0 * 4 + 2] + (t[i1 * 4 + 2] - t[i0 * 4 + 2]) * f
  ];
  const tl = Math.hypot(tangent[0], tangent[1], tangent[2]) || 1e-6;
  tangent[0] /= tl;
  tangent[1] /= tl;
  tangent[2] /= tl;
  return { position, tangent };
}
