import { createGLContext, type GLCaps } from '../core/gl';
import { FullscreenQuad } from '../core/glUtils';
import { GpuTimer } from '../core/gpuTimer';
import { buildInfinityPath, type InfinityPath } from '../path/infinity';
import { createPathTextures, type PathTextures } from '../path/pathTexture';
import { Simulation } from '../gpgpu/simulation';
import { Renderer, type Background } from '../render/renderer';
import type { OrbitCamera } from '../camera/orbit';
import type { ParamKey, Params } from '../params';

export interface SceneOptions {
  antialias?: boolean;
  transparent?: boolean;
}

/** Snapshot handed to the HUD once per frame. */
export interface SceneStats {
  count: number;
  arraySize: number;
  sortPasses: number;
  renderer: string;
  resolution: string;
  sortMs: number;
  stepMs: number;
  drawMs: number;
}

/**
 * Owns the GL context and every long-lived GPU resource (the ping-pong
 * simulation, the shared fullscreen quad, the path geometry/targets) plus the
 * drawing-buffer sizing. It exposes a frame-oriented API (`step`, `draw`) and a
 * single structural-reaction hook (`reactToChanges`) so callers never touch GL.
 */
export class GpuScene {
  readonly gl: WebGL2RenderingContext;
  readonly caps: GLCaps;

  private readonly canvas: HTMLCanvasElement;
  private readonly params: Params;
  private readonly quad: FullscreenQuad;
  private readonly path: InfinityPath;
  private readonly pathTex: PathTextures;
  private readonly renderer: Renderer;
  private readonly renderTimer: GpuTimer;
  private sim: Simulation;

  private renderW = 1;
  private renderH = 1;
  private pixelRatio = 1;

  constructor(canvas: HTMLCanvasElement, params: Params, options: SceneOptions = {}) {
    this.canvas = canvas;
    this.params = params;

    const { gl, caps } = createGLContext(canvas, {
      antialias: options.antialias,
      alpha: options.transparent
    });
    this.gl = gl;
    this.caps = caps;

    this.quad = new FullscreenQuad(gl);
    this.path = buildInfinityPath(params.pathSamples, params.pathScale);
    this.pathTex = createPathTextures(gl, this.path);
    this.sim = new Simulation(gl, this.quad, params, this.path, this.pathTex);

    const background: Background = !options.transparent
      ? 'sky'
      : caps.alpha
        ? 'transparent'
        : 'pattern';
    this.renderer = new Renderer(gl, this.quad, this.path, params, { background });
    this.renderTimer = new GpuTimer(gl, caps.timerQuery);

    this.resize();
  }

  /** Recomputes the drawing buffer from DPR cap and resolution scale. */
  resize(): void {
    const dpr =
      Math.min(window.devicePixelRatio || 1, this.params.dprCap) * this.params.resolutionScale;
    this.pixelRatio = dpr;
    const w = Math.max(1, Math.round(this.canvas.clientWidth * dpr));
    const h = Math.max(1, Math.round(this.canvas.clientHeight * dpr));
    if (w === this.renderW && h === this.renderH) return;
    this.renderW = w;
    this.renderH = h;
    this.canvas.width = w;
    this.canvas.height = h;
  }

  /** Reallocates the agent state (needed when `count` or `bins` changes). */
  rebuild(): void {
    this.sim.dispose();
    this.sim = new Simulation(this.gl, this.quad, this.params, this.path, this.pathTex);
  }

  /**
   * Applies the structural consequences of the given param keys: a new agent
   * array, a new drawing buffer, or a forced re-sort. Live uniforms need no
   * reaction — they are read from `Params` every pass.
   */
  reactToChanges(keys: readonly ParamKey[]): void {
    if (keys.some((k) => k === 'count' || k === 'bins')) this.rebuild();
    if (keys.some((k) => k === 'dprCap' || k === 'resolutionScale')) this.resize();
    if (keys.includes('sortInterval')) this.sim.markDirty();
  }

  step(dt: number, time: number): void {
    this.sim.step(dt, time);
  }

  draw(camera: OrbitCamera, time: number): void {
    this.renderTimer.begin();
    this.renderer.draw(camera, this.sim, this.params, time, this.renderW, this.renderH, this.pixelRatio);
    this.renderTimer.end();
  }

  stats(): SceneStats {
    return {
      count: this.params.count,
      arraySize: this.sim.arrays.arraySize,
      sortPasses: this.sim.sortPassCount,
      renderer: this.caps.renderer,
      resolution: `${this.renderW}x${this.renderH}`,
      sortMs: this.sim.pollSortMs(),
      stepMs: this.sim.pollStepMs(),
      drawMs: this.renderTimer.poll()
    };
  }

  dispose(): void {
    this.sim.dispose();
    this.renderer.dispose();
    this.quad.dispose();
  }
}
