import { parseConfig, serializeConfig, type BoidsConfig } from './schema';

/** Compact readable timestamp for filenames: 2026-10-17_14-30-05. */
function timestamp(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, '0');
  return (
    `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}` +
    `_${pad(d.getHours())}-${pad(d.getMinutes())}-${pad(d.getSeconds())}`
  );
}

export function defaultConfigFilename(): string {
  return `boids-config-${timestamp()}.json`;
}

export function downloadConfig(config: BoidsConfig, filename = defaultConfigFilename()): string {
  const json = serializeConfig(config);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  return filename;
}

export async function copyConfig(config: BoidsConfig): Promise<boolean> {
  const json = serializeConfig(config);
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(json);
      return true;
    }
  } catch {
    // fall through to legacy copy
  }
  return legacyCopy(json);
}

function legacyCopy(text: string): boolean {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.top = '-1000px';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    const ok = document.execCommand('copy');
    ta.remove();
    return ok;
  } catch {
    return false;
  }
}

export async function readConfigFile(file: File): Promise<BoidsConfig> {
  const text = await file.text();
  return parseConfig(text);
}
