import { App } from './app';
import type { Params } from './params';
import { GLInitError } from './core/gl';
import { escapeHtml } from './core/dom';

export interface BootstrapOptions {
  /** Initial parameters. The app mutates this object in place. */
  params: Params;
  /** Enable the parameter panel + config actions. Defaults to true. */
  ui?: boolean;
  /** Enable orbit/zoom input on the canvas. Defaults to true. */
  interactive?: boolean;
  /** Request an antialiased drawing buffer. Defaults to true. */
  antialias?: boolean;
  /** Transparent drawing buffer (skips the sky) so the page background shows. Defaults to false. */
  transparent?: boolean;
  /** Called once after construction, before the loop starts (e.g. apply a preset). */
  configure?: (app: App) => void;
}

export function bootstrap(options: BootstrapOptions): App {
  const canvas = document.getElementById('gl') as HTMLCanvasElement;
  try {
    const app = new App(canvas, options.params, {
      ui: options.ui,
      interactive: options.interactive,
      antialias: options.antialias,
      transparent: options.transparent
    });
    options.configure?.(app);
    app.start();
    window.addEventListener('beforeunload', () => app.dispose());
    (window as unknown as { __boids?: App }).__boids = app;
    return app;
  } catch (err) {
    if (err instanceof GLInitError) {
      showError(err.message, err.hint);
    } else {
      const message = err instanceof Error ? err.message : String(err);
      showError('Something went wrong', `<code>${escapeHtml(message)}</code>`);
    }
    throw err;
  }
}

function showError(title: string, body: string): void {
  const errorEl = document.getElementById('error');
  const errorTitle = document.getElementById('errorTitle');
  const errorBody = document.getElementById('errorBody');
  if (!errorEl || !errorTitle || !errorBody) return;
  errorTitle.textContent = title;
  errorBody.innerHTML = body;
  errorEl.classList.add('show');
}
