import { buildControls } from '../ui/controls';
import { buildConfigActions, showStatus } from '../ui/configActions';
import { copyConfig, downloadConfig, readConfigFile } from './io';
import type { BoidsConfig } from './schema';
import type { ParamKey, Params } from '../params';

export interface ConfigControllerHandlers {
  /** Snapshot of the live params + camera. */
  getConfig(): BoidsConfig;
  /** Hydrate params + camera from a parsed config. */
  applyConfig(config: BoidsConfig): void;
  /** Restore params, camera and GPU state to defaults. */
  resetToDefaults(): void;
  /** A single param changed via a control widget. */
  onParamChange(key: ParamKey): void;
}

/**
 * Bridges the control widgets and the save/load/reset/copy actions to the app.
 * Owns the panel contents and the transient status line; it holds no GPU or
 * camera state directly, only the injected callbacks.
 */
export class ConfigController {
  private statusEl: HTMLElement | null = null;

  constructor(
    private readonly container: HTMLElement | null,
    private readonly params: Params,
    private readonly handlers: ConfigControllerHandlers
  ) {
    this.refresh();
  }

  /** Rebuilds the widgets so they reflect the current `Params` (e.g. after load/reset). */
  refresh(): void {
    if (!this.container) return;
    this.container.innerHTML = '';
    buildControls(this.container, this.params, (key) => this.handlers.onParamChange(key));
    this.statusEl = buildConfigActions(this.container, {
      onSave: () => this.save(),
      onLoad: (file) => void this.load(file),
      onReset: () => this.reset(),
      onCopy: () => void this.copy()
    });
  }

  private save(): void {
    const filename = downloadConfig(this.handlers.getConfig());
    showStatus(this.statusEl, `Saved ${filename}`);
  }

  private async load(file: File): Promise<void> {
    try {
      const config = await readConfigFile(file);
      this.handlers.applyConfig(config);
      showStatus(this.statusEl, `Loaded ${file.name}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      showStatus(this.statusEl, `Load failed: ${message}`, true);
    }
  }

  private async copy(): Promise<void> {
    const ok = await copyConfig(this.handlers.getConfig());
    showStatus(this.statusEl, ok ? 'Copied config JSON' : 'Copy failed', !ok);
  }

  private reset(): void {
    this.handlers.resetToDefaults();
    this.refresh();
    showStatus(this.statusEl, 'Reset to defaults');
  }
}
