import type { InfinityPath } from '../path/infinity';

export interface MeshData {
  /** Interleaved [px,py,pz, nx,ny,nz] triangles. */
  vertices: Float32Array;
  vertexCount: number;
}

function pushTri(
  out: number[],
  a: [number, number, number],
  b: [number, number, number],
  c: [number, number, number]
): void {
  const ux = b[0] - a[0];
  const uy = b[1] - a[1];
  const uz = b[2] - a[2];
  const vx = c[0] - a[0];
  const vy = c[1] - a[1];
  const vz = c[2] - a[2];
  let nx = uy * vz - uz * vy;
  let ny = uz * vx - ux * vz;
  let nz = ux * vy - uy * vx;
  const len = Math.hypot(nx, ny, nz) || 1e-6;
  nx /= len;
  ny /= len;
  nz /= len;
  out.push(a[0], a[1], a[2], nx, ny, nz);
  out.push(b[0], b[1], b[2], nx, ny, nz);
  out.push(c[0], c[1], c[2], nx, ny, nz);
}

/** A stretched octahedron: reads as a faceted dart oriented along +Z. */
export function buildBoidMesh(): MeshData {
  const front: [number, number, number] = [0, 0, 0.62];
  const back: [number, number, number] = [0, 0, -0.34];
  const w = 0.16;
  const equator: [number, number, number][] = [
    [w, 0, 0],
    [0, w, 0],
    [-w, 0, 0],
    [0, -w, 0]
  ];
  const out: number[] = [];
  for (let i = 0; i < 4; i++) {
    const a = equator[i];
    const b = equator[(i + 1) % 4];
    pushTri(out, front, a, b);
    pushTri(out, back, b, a);
  }
  return { vertices: new Float32Array(out), vertexCount: out.length / 6 };
}

/** Builds a tube mesh around the infinity curve using parallel-transport frames. */
export function buildPathTube(path: InfinityPath, radius: number, sides: number): MeshData {
  const n = path.sampleCount;
  const pos = path.positions;
  const tan = path.tangents;

  let tx = tan[0];
  let ty = tan[1];
  let tz = tan[2];
  let tl = Math.hypot(tx, ty, tz) || 1e-6;
  tx /= tl;
  ty /= tl;
  tz /= tl;

  let nx = -ty;
  let ny = tx;
  let nz = 0;
  let nl = Math.hypot(nx, ny, nz);
  if (nl < 1e-4) {
    nx = 1;
    ny = 0;
    nz = 0;
    nl = 1;
  }
  nx /= nl;
  ny /= nl;
  nz /= nl;

  const ringN = new Float32Array(n * 3);
  const ringB = new Float32Array(n * 3);
  const centers = new Float32Array(n * 3);
  const ringCos = new Float32Array(sides);
  const ringSin = new Float32Array(sides);
  for (let s = 0; s < sides; s++) {
    const ang = (s / sides) * Math.PI * 2;
    ringCos[s] = Math.cos(ang);
    ringSin[s] = Math.sin(ang);
  }

  for (let i = 0; i < n; i++) {
    let t0x = tan[i * 4 + 0];
    let t0y = tan[i * 4 + 1];
    let t0z = tan[i * 4 + 2];
    const t0l = Math.hypot(t0x, t0y, t0z) || 1e-6;
    t0x /= t0l;
    t0y /= t0l;
    t0z /= t0l;

    if (i > 0) {
      const dot = nx * t0x + ny * t0y + nz * t0z;
      nx -= t0x * dot;
      ny -= t0y * dot;
      nz -= t0z * dot;
      const l = Math.hypot(nx, ny, nz);
      if (l < 1e-5) {
        nx = -t0y;
        ny = t0x;
        nz = 0;
        const l2 = Math.hypot(nx, ny, nz) || 1;
        nx /= l2;
        ny /= l2;
        nz /= l2;
      } else {
        nx /= l;
        ny /= l;
        nz /= l;
      }
    }

    const bx = t0y * nz - t0z * ny;
    const by = t0z * nx - t0x * nz;
    const bz = t0x * ny - t0y * nx;

    ringN[i * 3 + 0] = nx;
    ringN[i * 3 + 1] = ny;
    ringN[i * 3 + 2] = nz;
    ringB[i * 3 + 0] = bx;
    ringB[i * 3 + 1] = by;
    ringB[i * 3 + 2] = bz;
    centers[i * 3 + 0] = pos[i * 4 + 0];
    centers[i * 3 + 1] = pos[i * 4 + 1];
    centers[i * 3 + 2] = pos[i * 4 + 2];
  }

  const vertexOf = (i: number, s: number, out: [number, number, number]): [number, number, number] => {
    const c = ringCos[s];
    const sn = ringSin[s];
    const px = centers[i * 3 + 0] + radius * (ringN[i * 3 + 0] * c + ringB[i * 3 + 0] * sn);
    const py = centers[i * 3 + 1] + radius * (ringN[i * 3 + 1] * c + ringB[i * 3 + 1] * sn);
    const pz = centers[i * 3 + 2] + radius * (ringN[i * 3 + 2] * c + ringB[i * 3 + 2] * sn);
    out[0] = px;
    out[1] = py;
    out[2] = pz;
    return out;
  };

  const out: number[] = [];
  const a: [number, number, number] = [0, 0, 0];
  const b: [number, number, number] = [0, 0, 0];
  const c: [number, number, number] = [0, 0, 0];
  const d: [number, number, number] = [0, 0, 0];
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    for (let s = 0; s < sides; s++) {
      const s2 = (s + 1) % sides;
      vertexOf(i, s, a);
      vertexOf(j, s, b);
      vertexOf(j, s2, c);
      vertexOf(i, s2, d);
      pushTri(out, a, b, c);
      pushTri(out, a, c, d);
    }
  }
  return { vertices: new Float32Array(out), vertexCount: out.length / 6 };
}
