export interface ConfigActionHandlers {
  onSave(): void;
  onLoad(file: File): void;
  onReset(): void;
  onCopy(): void;
}

function makeButton(label: string, onClick: () => void): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'action';
  button.textContent = label;
  button.addEventListener('click', onClick);
  return button;
}

/**
 * Renders the save/load/reset/copy controls into the given container and
 * returns the status element so the app can report results.
 */
export function buildConfigActions(
  container: HTMLElement,
  handlers: ConfigActionHandlers
): HTMLElement {
  const section = document.createElement('div');
  section.className = 'group';

  const title = document.createElement('div');
  title.className = 'title';
  title.textContent = 'Config';
  section.appendChild(title);

  const row = document.createElement('div');
  row.className = 'actions';

  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = 'application/json,.json';
  fileInput.style.display = 'none';
  fileInput.addEventListener('change', () => {
    const file = fileInput.files?.[0];
    if (file) handlers.onLoad(file);
    fileInput.value = '';
  });

  const saveBtn = makeButton('Save', () => handlers.onSave());
  const loadBtn = makeButton('Load', () => fileInput.click());
  const resetBtn = makeButton('Reset', () => handlers.onReset());
  const copyBtn = makeButton('Copy', () => handlers.onCopy());

  row.append(saveBtn, loadBtn, resetBtn, copyBtn, fileInput);
  section.appendChild(row);

  const status = document.createElement('div');
  status.className = 'status';
  section.appendChild(status);

  container.appendChild(section);
  return status;
}

interface StatusEl extends HTMLElement {
  __statusTimer?: number;
}

export function showStatus(el: HTMLElement | null, message: string, isError = false): void {
  if (!el) return;
  const node = el as StatusEl;
  node.textContent = message;
  node.classList.toggle('error', isError);
  node.classList.toggle('ok', !isError);
  if (node.__statusTimer) window.clearTimeout(node.__statusTimer);
  node.__statusTimer = window.setTimeout(() => {
    node.textContent = '';
    node.classList.remove('ok', 'error');
    node.__statusTimer = undefined;
  }, 2600);
}
