import { FRAG_HEADER } from './common';

/**
 * Assigns each agent a spatial bin derived from its arc-length parameter, then
 * packs `(bin, agentIndex)` into a single 32-bit unsigned integer:
 *
 *     packed = bin * 2^uIndexBits + index        (bitwise: (bin << bits) | index)
 *
 * `arraySize` is always a power of two, so `index < 2^uIndexBits` and the packed
 * value orders lexicographically by `(bin, index)`. Padding slots receive bin
 * `uBins` (one past the last real bin) so the sort pushes them to the tail.
 *
 * Writing one `uint` (R32UI, 4 B) instead of an `RGBA32F` (16 B) texel cuts the
 * dominant bitonic bandwidth by 4x.
 */
export const BIN_FRAG = `${FRAG_HEADER}
uniform sampler2D uPos;
uniform int uArrayW;
uniform int uCount;
uniform int uBins;
uniform int uIndexBits;

out uint outColor;

void main() {
  int x = int(gl_FragCoord.x);
  int y = int(gl_FragCoord.y);
  int index = y * uArrayW + x;
  uint stride = 1u << uint(uIndexBits);
  if (index >= uCount) {
    outColor = uint(uBins) * stride + uint(index);
    return;
  }
  vec4 p = texelFetch(uPos, ivec2(x, y), 0);
  float s = p.w;
  uint bin = uint(clamp(floor(s * float(uBins)), 0.0, float(uBins - 1)));
  outColor = bin * stride + uint(index);
}
`;

/**
 * One comparator substage of a bitonic sorting network over packed `(bin,index)`
 * keys. The CPU drives the (stage, sub) uniforms; every texel reads its partner
 * and keeps min or max of the packed key depending on block direction.
 */
export const BITONIC_FRAG = `${FRAG_HEADER}
uniform usampler2D uData;
uniform int uArrayW;
uniform int uArraySize;
uniform int uStage;
uniform int uSub;

out uint outColor;

ivec2 coordOf(int i) {
  return ivec2(i % uArrayW, i / uArrayW);
}

void main() {
  int i = int(gl_FragCoord.y) * uArrayW + int(gl_FragCoord.x);
  if (i >= uArraySize) {
    outColor = 0xFFFFFFFFu;
    return;
  }
  int partner = i ^ uSub;
  uint ka = texelFetch(uData, coordOf(i), 0).x;
  uint kb = texelFetch(uData, coordOf(partner), 0).x;

  bool iIsLow = (i & uSub) == 0;
  bool ascending = (i & uStage) == 0;
  bool wantMin = (ascending == iIsLow);
  bool takeA = wantMin ? (ka <= kb) : (ka >= kb);
  outColor = takeA ? ka : kb;
}
`;

/**
 * Gathers agent state into bin-sorted order (Tier 2). For each sorted slot `j`
 * the packed key decodes to a source agent index; the position/velocity are read
 * once from that index and written to slot `j`. The boids step then reads
 * neighbours *contiguously* from the sorted arrays instead of scattering random
 * `texelFetch`es through the unsorted state (one gather per agent per frame,
 * regular and uniform, instead of one random read per neighbour in a divergent
 * loop). The agent index is carried in `outPos.w` so the step can still skip
 * itself without a second key fetch (indices up to 2^24 are exact in float32).
 *
 * Runs every frame (state changes each step even when the sort order does not),
 * so it is timed as part of the step, not the sort.
 */
export const GATHER_FRAG = `${FRAG_HEADER}
uniform usampler2D uSort;
uniform sampler2D uPos;
uniform sampler2D uVel;
uniform int uArrayW;
uniform int uIndexBits;

layout(location = 0) out vec4 outPos;
layout(location = 1) out vec4 outVel;

ivec2 coordOf(int i) {
  return ivec2(i % uArrayW, i / uArrayW);
}

void main() {
  ivec2 c = ivec2(gl_FragCoord.xy);
  uint packed = texelFetch(uSort, c, 0).x;
  int src = int(packed & ((1u << uint(uIndexBits)) - 1u));
  vec4 p = texelFetch(uPos, coordOf(src), 0);
  vec4 v = texelFetch(uVel, coordOf(src), 0);
  outPos = vec4(p.xyz, float(src));
  outVel = v;
}
`;

/**
 * For each bin, binary-searches the sorted key array to record the start offset
 * and element count. This is the histogram/prefix-sum equivalent done without
 * atomics (which WebGL2 fragment shaders lack). The packed key is decoded back
 * to its bin by shifting out the index bits.
 */
export const OFFSETS_FRAG = `${FRAG_HEADER}
uniform usampler2D uSort;
uniform int uArrayW;
uniform int uArraySize;
uniform int uBins;
uniform int uIndexBits;

out vec4 outColor;

float keyAt(int i) {
  uint packed = texelFetch(uSort, ivec2(i % uArrayW, i / uArrayW), 0).x;
  return float(packed >> uint(uIndexBits));
}

int lowerBound(float target) {
  int lo = 0;
  int hi = uArraySize;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    if (keyAt(mid) < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

int upperBound(float target) {
  int lo = 0;
  int hi = uArraySize;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    if (keyAt(mid) <= target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

void main() {
  int bin = int(gl_FragCoord.x);
  if (bin >= uBins) {
    outColor = vec4(0.0);
    return;
  }
  float target = float(bin);
  int start = lowerBound(target);
  int end = upperBound(target);
  outColor = vec4(float(start), float(max(end - start, 0)), 0.0, 0.0);
}
`;
