import { GpuScene } from './scene/gpuScene';
import { Loop } from './scene/loop';
import { OrbitCamera } from './camera/orbit';
import { Hud } from './ui/hud';
import { Panel } from './ui/panel';
import { ConfigController } from './config/controller';
import { applyParams, captureConfig, type BoidsConfig } from './config/schema';
import { DEFAULT_PARAMS, type Params } from './params';

export interface AppOptions {
  ui?: boolean;
  interactive?: boolean;
  antialias?: boolean;
  transparent?: boolean;
}

/**
 * Top-level coordinator: wires the GPU scene, camera, HUD, panel and config
 * controller together and exposes the small surface the entry points need
 * (`applyConfig`, `start`, `stop`, `dispose`). Holds no GL state itself.
 */
export class App {
  private readonly scene: GpuScene;
  private readonly camera: OrbitCamera;
  private readonly hud: Hud | null;
  private readonly panel: Panel | null;
  private readonly controller: ConfigController | null;
  private readonly loop: Loop;

  constructor(
    canvas: HTMLCanvasElement,
    private readonly params: Params,
    options: AppOptions = {}
  ) {
    const ui = options.ui ?? true;
    const interactive = options.interactive ?? true;

    this.scene = new GpuScene(canvas, params, {
      antialias: options.antialias,
      transparent: options.transparent
    });

    this.camera = new OrbitCamera(canvas, interactive);
    this.camera.autorotate = params.autorotate;

    const hudEl = document.getElementById('hud');
    this.hud = hudEl ? new Hud(hudEl) : null;
    this.panel = ui ? Panel.mount() : null;
    this.controller = ui
      ? new ConfigController(document.getElementById('controls'), params, {
          getConfig: () => this.getConfig(),
          applyConfig: (config) => this.applyConfig(config),
          resetToDefaults: () => this.resetToDefaults(),
          onParamChange: (key) => this.scene.reactToChanges([key])
        })
      : null;

    this.loop = new Loop(this.scene, this.camera, params, this.hud);
    window.addEventListener('resize', this.handleResize);
  }

  private handleResize = (): void => this.scene.resize();

  getConfig(): BoidsConfig {
    return captureConfig(this.params, this.camera.getState());
  }

  applyConfig(config: BoidsConfig): void {
    const changed = applyParams(this.params, config.params);
    this.camera.setState(config.camera);
    this.camera.autorotate = this.params.autorotate;
    this.scene.reactToChanges(changed);
    this.controller?.refresh();
  }

  private resetToDefaults(): void {
    Object.assign(this.params, DEFAULT_PARAMS);
    this.camera.reset();
    this.camera.autorotate = this.params.autorotate;
    this.scene.rebuild();
    this.scene.resize();
  }

  start(): void {
    this.loop.start();
  }

  stop(): void {
    this.loop.stop();
  }

  dispose(): void {
    this.loop.dispose();
    window.removeEventListener('resize', this.handleResize);
    this.panel?.dispose();
    this.camera.dispose();
    this.scene.dispose();
  }
}
