import type { Program } from '../core/glUtils';
import { FullscreenQuad, createFloatTexture, createUintTexture, createFramebuffer, createProgram } from '../core/glUtils';
import { GpuTimer } from '../core/gpuTimer';
import { FULLSCREEN_VERT } from '../shaders/common';
import { BIN_FRAG, BITONIC_FRAG, OFFSETS_FRAG, GATHER_FRAG } from '../shaders/sim';
import { BOIDS_FRAG } from '../shaders/boids';
import type { PathTextures } from '../path/pathTexture';
import { samplePath, type InfinityPath } from '../path/infinity';
import type { Params } from '../params';

function nextPow2(x: number): number {
  let p = 1;
  while (p < x) p <<= 1;
  return p;
}

function log2i(x: number): number {
  let bits = 0;
  while ((1 << bits) < x) bits++;
  return bits;
}

export interface SimArrays {
  arrayW: number;
  arrayH: number;
  arraySize: number;
  indexBits: number;
}

export class Simulation {
  readonly arrays: SimArrays;
  private readonly gl: WebGL2RenderingContext;
  private readonly quad: FullscreenQuad;
  private readonly params: Params;
  private readonly path: InfinityPath;
  private readonly pathTex: PathTextures;

  private readonly binProgram: Program;
  private readonly bitonicProgram: Program;
  private readonly offsetsProgram: Program;
  private readonly gatherProgram: Program;
  private readonly boidsProgram: Program;

  private readonly posTex: [WebGLTexture, WebGLTexture];
  private readonly velTex: [WebGLTexture, WebGLTexture];
  private readonly simFbo: [WebGLFramebuffer, WebGLFramebuffer];
  private readonly sortTex: [WebGLTexture, WebGLTexture];
  private readonly sortFbo: [WebGLFramebuffer, WebGLFramebuffer];
  private readonly offsetsTex: WebGLTexture;
  private readonly offsetsFbo: WebGLFramebuffer;
  private readonly sortedPosTex: WebGLTexture;
  private readonly sortedVelTex: WebGLTexture;
  private readonly sortedFbo: WebGLFramebuffer;

  private simIndex = 0;
  private sortIndex = 0;
  private frame = 0;
  private needsSort = true;

  /** GPU timing split: sort = bin+bitonic+offsets, step = gather + boids integration. */
  private readonly sortTimer: GpuTimer;
  private readonly stepTimer: GpuTimer;

  private readonly stages: Array<[number, number]> = [];

  constructor(
    gl: WebGL2RenderingContext,
    quad: FullscreenQuad,
    params: Params,
    path: InfinityPath,
    pathTex: PathTextures
  ) {
    this.gl = gl;
    this.quad = quad;
    this.params = params;
    this.path = path;
    this.pathTex = pathTex;

    const w = nextPow2(Math.max(1, Math.ceil(Math.sqrt(params.count))));
    const h = nextPow2(Math.max(1, Math.ceil(params.count / w)));
    this.arrays = { arrayW: w, arrayH: h, arraySize: w * h, indexBits: log2i(w * h) };

    this.binProgram = createProgram(gl, FULLSCREEN_VERT, BIN_FRAG);
    this.bitonicProgram = createProgram(gl, FULLSCREEN_VERT, BITONIC_FRAG);
    this.offsetsProgram = createProgram(gl, FULLSCREEN_VERT, OFFSETS_FRAG);
    this.gatherProgram = createProgram(gl, FULLSCREEN_VERT, GATHER_FRAG);
    this.boidsProgram = createProgram(gl, FULLSCREEN_VERT, BOIDS_FRAG);

    const { arrayW, arrayH, arraySize } = this.arrays;

    const { posData, velData } = this.buildInitialState(arraySize, params);
    const posA = createFloatTexture(gl, arrayW, arrayH, posData);
    const velA = createFloatTexture(gl, arrayW, arrayH, velData);
    const posB = createFloatTexture(gl, arrayW, arrayH, null);
    const velB = createFloatTexture(gl, arrayW, arrayH, null);
    this.posTex = [posA, posB];
    this.velTex = [velA, velB];
    this.simFbo = [
      createFramebuffer(gl, [posA, velA]),
      createFramebuffer(gl, [posB, velB])
    ];

    const sA = createUintTexture(gl, arrayW, arrayH);
    const sB = createUintTexture(gl, arrayW, arrayH);
    this.sortTex = [sA, sB];
    this.sortFbo = [createFramebuffer(gl, [sA]), createFramebuffer(gl, [sB])];

    this.offsetsTex = createFloatTexture(gl, params.bins, 1, null);
    this.offsetsFbo = createFramebuffer(gl, [this.offsetsTex]);

    this.sortedPosTex = createFloatTexture(gl, arrayW, arrayH, null);
    this.sortedVelTex = createFloatTexture(gl, arrayW, arrayH, null);
    this.sortedFbo = createFramebuffer(gl, [this.sortedPosTex, this.sortedVelTex]);

    this.sortTimer = new GpuTimer(gl);
    this.stepTimer = new GpuTimer(gl);

    this.buildSortStages(arraySize);
  }

  private buildInitialState(
    arraySize: number,
    params: Params
  ): { posData: Float32Array; velData: Float32Array } {
    const posData = new Float32Array(arraySize * 4);
    const velData = new Float32Array(arraySize * 4);
    const count = params.count;
    const path = this.path;

    for (let i = 0; i < count; i++) {
      const s = Math.random();
      const sample = samplePath(path, s);
      const t = sample.tangent;
      let upx = 0;
      let upy = 1;
      let upz = 0;
      if (Math.abs(t[1]) > 0.9) {
        upx = 1;
        upy = 0;
        upz = 0;
      }
      let rx = t[1] * upz - t[2] * upy;
      let ry = t[2] * upx - t[0] * upz;
      let rz = t[0] * upy - t[1] * upx;
      let rl = Math.hypot(rx, ry, rz) || 1;
      rx /= rl;
      ry /= rl;
      rz /= rl;
      const bx = t[1] * rz - t[2] * ry;
      const by = t[2] * rx - t[0] * rz;
      const bz = t[0] * ry - t[1] * rx;

      const ang = Math.random() * Math.PI * 2;
      const radius = Math.sqrt(Math.random()) * params.pathRadius * 0.7;
      const ca = Math.cos(ang) * radius;
      const sa = Math.sin(ang) * radius;

      posData[i * 4 + 0] = sample.position[0] + rx * ca + bx * sa;
      posData[i * 4 + 1] = sample.position[1] + ry * ca + by * sa;
      posData[i * 4 + 2] = sample.position[2] + rz * ca + bz * sa;
      posData[i * 4 + 3] = s;

      const speed = params.desiredSpeed * (0.7 + Math.random() * 0.6);
      velData[i * 4 + 0] = t[0] * speed + (Math.random() - 0.5) * 0.2;
      velData[i * 4 + 1] = t[1] * speed + (Math.random() - 0.5) * 0.2;
      velData[i * 4 + 2] = t[2] * speed + (Math.random() - 0.5) * 0.2;
      velData[i * 4 + 3] = Math.random() * 1000;
    }
    return { posData, velData };
  }

  private buildSortStages(arraySize: number): void {
    this.stages.length = 0;
    for (let k = 2; k <= arraySize; k <<= 1) {
      for (let j = k >> 1; j > 0; j >>= 1) {
        this.stages.push([k, j]);
      }
    }
  }

  private bindTexture(unit: number, tex: WebGLTexture, location: WebGLUniformLocation | null): void {
    const gl = this.gl;
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.uniform1i(location, unit);
  }

  private drawTo(fbo: WebGLFramebuffer | null, width: number, height: number): void {
    const gl = this.gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    gl.viewport(0, 0, width, height);
    this.quad.draw();
  }

  private runBinPass(): void {
    const gl = this.gl;
    const p = this.binProgram;
    gl.useProgram(p.program);
    this.bindTexture(0, this.posTex[this.simIndex], p.uniforms.uPos);
    gl.uniform1i(p.uniforms.uArrayW, this.arrays.arrayW);
    gl.uniform1i(p.uniforms.uCount, this.params.count);
    gl.uniform1i(p.uniforms.uBins, this.params.bins);
    gl.uniform1i(p.uniforms.uIndexBits, this.arrays.indexBits);
    gl.disable(gl.BLEND);
    gl.disable(gl.DEPTH_TEST);
    gl.disable(gl.CULL_FACE);
    this.drawTo(this.sortFbo[0], this.arrays.arrayW, this.arrays.arrayH);
    this.sortIndex = 0;
  }

  private runBitonicSort(): void {
    const gl = this.gl;
    const p = this.bitonicProgram;
    gl.useProgram(p.program);
    gl.uniform1i(p.uniforms.uArrayW, this.arrays.arrayW);
    gl.uniform1i(p.uniforms.uArraySize, this.arrays.arraySize);
    gl.uniform1i(p.uniforms.uData, 0);
    for (const [stage, sub] of this.stages) {
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, this.sortTex[this.sortIndex]);
      gl.uniform1i(p.uniforms.uStage, stage);
      gl.uniform1i(p.uniforms.uSub, sub);
      const write = 1 - this.sortIndex;
      this.drawTo(this.sortFbo[write], this.arrays.arrayW, this.arrays.arrayH);
      this.sortIndex = write;
    }
  }

  private runOffsetsPass(): void {
    const gl = this.gl;
    const p = this.offsetsProgram;
    gl.useProgram(p.program);
    this.bindTexture(0, this.sortTex[this.sortIndex], p.uniforms.uSort);
    gl.uniform1i(p.uniforms.uArrayW, this.arrays.arrayW);
    gl.uniform1i(p.uniforms.uArraySize, this.arrays.arraySize);
    gl.uniform1i(p.uniforms.uBins, this.params.bins);
    gl.uniform1i(p.uniforms.uIndexBits, this.arrays.indexBits);
    this.drawTo(this.offsetsFbo, this.params.bins, 1);
  }

  /**
   * Bins scanned each side of the agent's own bin. When `neighborBins` is 0 the
   * window is derived so it exactly spans `neighborRadius` in arc length:
   * `R = ceil(neighborRadius / binWidth)`, `binWidth = pathLength / bins`.
   */
  private neighborBins(): number {
    const params = this.params;
    if (params.neighborBins > 0) return Math.max(1, Math.round(params.neighborBins));
    const binWidth = this.path.length / Math.max(1, params.bins);
    return Math.max(1, Math.ceil(params.neighborRadius / binWidth));
  }

  /**
   * Reorders the current agent state into bin-sorted order so the boids step can
   * read neighbours contiguously. Derived from the (possibly stale) sort order
   * and the current positions, so it runs every frame.
   */
  private runGatherPass(): void {
    const gl = this.gl;
    const p = this.gatherProgram;
    gl.useProgram(p.program);
    this.bindTexture(0, this.sortTex[this.sortIndex], p.uniforms.uSort);
    this.bindTexture(1, this.posTex[this.simIndex], p.uniforms.uPos);
    this.bindTexture(2, this.velTex[this.simIndex], p.uniforms.uVel);
    gl.uniform1i(p.uniforms.uArrayW, this.arrays.arrayW);
    gl.uniform1i(p.uniforms.uIndexBits, this.arrays.indexBits);
    gl.disable(gl.BLEND);
    gl.disable(gl.DEPTH_TEST);
    this.drawTo(this.sortedFbo, this.arrays.arrayW, this.arrays.arrayH);
  }

  private runBoidsPass(dt: number, time: number): void {
    const gl = this.gl;
    const p = this.boidsProgram;
    const params = this.params;
    const { arrayW, arrayH } = this.arrays;

    const read = this.simIndex;
    const write = 1 - this.simIndex;

    gl.useProgram(p.program);
    this.bindTexture(0, this.posTex[read], p.uniforms.uPos);
    this.bindTexture(1, this.velTex[read], p.uniforms.uVel);
    this.bindTexture(2, this.sortedPosTex, p.uniforms.uSortedPos);
    this.bindTexture(3, this.sortedVelTex, p.uniforms.uSortedVel);
    this.bindTexture(4, this.offsetsTex, p.uniforms.uOffsets);
    this.bindTexture(5, this.pathTex.posTex, p.uniforms.uPathPos);
    this.bindTexture(6, this.pathTex.tanTex, p.uniforms.uPathTan);

    gl.uniform1i(p.uniforms.uArrayW, arrayW);
    gl.uniform1i(p.uniforms.uCount, params.count);
    gl.uniform1i(p.uniforms.uBins, params.bins);
    gl.uniform1i(p.uniforms.uPathSamples, this.pathTex.sampleCount);
    gl.uniform1i(p.uniforms.uNeighborBins, this.neighborBins());
    gl.uniform1i(p.uniforms.uPerBinCap, params.perBinCap);
    gl.uniform1i(p.uniforms.uMaxNeighbors, params.maxNeighbors);

    gl.uniform1f(p.uniforms.uDt, dt);
    gl.uniform1f(p.uniforms.uTime, time);
    gl.uniform1f(p.uniforms.uPathLength, this.path.length);
    gl.uniform1f(p.uniforms.uNeighborRadius, params.neighborRadius);
    gl.uniform1f(p.uniforms.uSeparationRadius, params.separationRadius);
    gl.uniform1f(p.uniforms.uMaxSpeed, params.maxSpeed);
    gl.uniform1f(p.uniforms.uMinSpeed, params.minSpeed);
    gl.uniform1f(p.uniforms.uMaxForce, params.maxForce);
    gl.uniform1f(p.uniforms.uDesiredSpeed, params.desiredSpeed);
    gl.uniform1f(p.uniforms.uPathStrength, params.pathStrength);
    gl.uniform1f(p.uniforms.uPathRadius, params.pathRadius);
    gl.uniform1f(p.uniforms.uSeparationWeight, params.separationWeight);
    gl.uniform1f(p.uniforms.uAlignmentWeight, params.alignmentWeight);
    gl.uniform1f(p.uniforms.uCohesionWeight, params.cohesionWeight);
    gl.uniform1f(p.uniforms.uFlowStrength, params.flowStrength);
    gl.uniform1f(p.uniforms.uRadialDamping, params.radialDamping);
    gl.uniform1f(p.uniforms.uNoiseStrength, params.noiseStrength);
    gl.uniform1f(p.uniforms.uProgression, params.progression);

    gl.disable(gl.BLEND);
    gl.disable(gl.DEPTH_TEST);
    this.drawTo(this.simFbo[write], arrayW, arrayH);
    this.simIndex = write;
  }

  step(dt: number, time: number): void {
    const interval = Math.max(1, Math.round(this.params.sortInterval));
    if (this.needsSort || this.frame % interval === 0) {
      if (this.sortTimer.supported) this.sortTimer.begin();
      this.runBinPass();
      this.runBitonicSort();
      this.runOffsetsPass();
      if (this.sortTimer.supported) this.sortTimer.end();
      this.needsSort = false;
    }
    this.stepTimer.begin();
    this.runGatherPass();
    this.runBoidsPass(dt, time);
    this.stepTimer.end();
    this.frame++;
  }

  /** GPU ms for the last sort group (bin + bitonic + offsets). */
  pollSortMs(): number {
    return this.sortTimer.poll();
  }

  /** GPU ms for the boids neighbour-gather + integration pass. */
  pollStepMs(): number {
    return this.stepTimer.poll();
  }

  markDirty(): void {
    this.needsSort = true;
  }

  get positionTexture(): WebGLTexture {
    return this.posTex[this.simIndex];
  }

  get velocityTexture(): WebGLTexture {
    return this.velTex[this.simIndex];
  }

  get arrayWidth(): number {
    return this.arrays.arrayW;
  }

  get sortPassCount(): number {
    return this.stages.length;
  }

  dispose(): void {
    const gl = this.gl;
    gl.deleteTexture(this.posTex[0]);
    gl.deleteTexture(this.posTex[1]);
    gl.deleteTexture(this.velTex[0]);
    gl.deleteTexture(this.velTex[1]);
    gl.deleteTexture(this.sortTex[0]);
    gl.deleteTexture(this.sortTex[1]);
    gl.deleteTexture(this.offsetsTex);
    gl.deleteTexture(this.sortedPosTex);
    gl.deleteTexture(this.sortedVelTex);
    gl.deleteFramebuffer(this.simFbo[0]);
    gl.deleteFramebuffer(this.simFbo[1]);
    gl.deleteFramebuffer(this.sortFbo[0]);
    gl.deleteFramebuffer(this.sortFbo[1]);
    gl.deleteFramebuffer(this.offsetsFbo);
    gl.deleteFramebuffer(this.sortedFbo);
    gl.deleteProgram(this.binProgram.program);
    gl.deleteProgram(this.bitonicProgram.program);
    gl.deleteProgram(this.offsetsProgram.program);
    gl.deleteProgram(this.gatherProgram.program);
    gl.deleteProgram(this.boidsProgram.program);
    this.sortTimer.dispose();
    this.stepTimer.dispose();
  }
}
