import type { Params } from './params';

/**
 * Coarse mobile/tablet detection. Used only to pick cheaper *defaults*; every
 * value stays user-tunable in the panel, so a mis-detection is cosmetic.
 */
export function detectMobile(): boolean {
  if (typeof navigator === 'undefined') return false;
  const ua = navigator.userAgent || '';
  if (/Android|iPhone|iPad|iPod|Mobile|Silk|Kindle/i.test(ua)) return true;
  // iPadOS 13+ masquerades as desktop Safari; a multitouch "Mac" is an iPad.
  const macLike = /Macintosh/.test(ua);
  const touch = typeof navigator.maxTouchPoints === 'number' && navigator.maxTouchPoints > 1;
  return macLike && touch;
}

/**
 * Mobile overrides. The GPU cost is dominated by the bitonic sort's fill-rate and
 * pass count, which budget phones pay for disproportionately, so we sort less
 * often (the ribbon is path-locked and reorders slowly) and shrink the neighbour
 * gather. MSAA is disabled separately via the context `antialias` flag.
 */
export const MOBILE_DEFAULTS: Partial<Params> = {
  dprCap: 1.5,
  resolutionScale: 0.6,
  sortInterval: 4,
  maxNeighbors: 32,
  perBinCap: 16,
  neighborBins: 16,
  showPath: false
};

export function applyMobileDefaults(params: Params): void {
  Object.assign(params, MOBILE_DEFAULTS);
}
